  function registerVehicle(){modal(tr('تسجيل مركبتي','Register my vehicle'),`<form class="form-columns">${vehicleFields(state.user.vehicle||{})}${notice(tr('يمكنك إدخال المركبة إن لم تكن مسجلة. بعد الحفظ يكون التعديل لمدير التوصيل فقط.','You can register a missing vehicle. After saving, only the manager can change it.'))}${formEnd(tr('حفظ المركبة','Save vehicle'))}</form>`,async fd=>{const result=await api('/api/identity/driver/vehicle',{method:'PUT',body:vehicleValue(fd)});state.user.vehicle=result.vehicle;closeModal();await loadPage();});}
  const printStatus = status => ({queued:tr('بانتظار الكمبيوتر','Waiting for computer'),claimed:tr('استلمها الكمبيوتر — تحقق من الطابعة','Computer received — check printer'),submitted:tr('أرسلت لويندوز — خروج الورق غير مؤكد','Submitted to Windows — paper unconfirmed'),uncertain:tr('غير مؤكد — راجع قبل الإعادة','Uncertain — check before reprint'),cancelled:tr('ملغي','Cancelled')})[status]||status;
