  function printerStatus(x){return {online:tr('متصل','Connected'),offline:tr('غير متصل','Offline'),pending:tr('بانتظار الربط','Awaiting connection'),revoked:tr('ألغي الربط','Revoked')}[x.connection_status]||tr('غير معروف','Unknown');}
  function printerNotes(x){if(x.connection_status==='offline')return tr('لا يوجد اتصال ببرنامج الطباعة؛ تحقق من الإنترنت وتشغيل الكمبيوتر والبرنامج. لا يمكن تأكيد السكون من انقطاع الاتصال وحده.','No connection to the print program. Check internet, computer and program. Disconnection alone does not confirm sleep.');if(x.connection_status==='pending')return tr('افتح إعداد الفرع على كمبيوتر الفرع واختر الطابعة ثم اضغط ربط.','Open branch setup on its computer, select the printer and connect.');return x.approved_at?tr('اجتاز الاختبار واعتمده المسؤول','Test confirmed and approved by operator'):tr('يلزم طباعة صفحة اختبار ثم اعتماد خروج الورقة.','Print a test, then confirm physical output.');}
  function printerRows(devices,branchId=null){return `<section class="printer-directory">`+table([tr('الفرع','Branch'),tr('الطابعة','Printer'),tr('الحالة','Status'),tr('ملاحظات النظام','System notes'),tr('آخر اتصال','Last connection'),tr('الإجراء','Action')],devices.filter(x=>!x.revoked_at&&(!branchId||x.branch_id===branchId)).map(x=>[esc(branchLabel(x.branch_id)),esc(x.printer_name||'—'),`<span class="pill ${x.connection_status==='online'&&x.approved_at?'good':'warn'}">${esc(printerStatus(x))}${x.approved_at?' · ✅ '+esc(tr('معتمد','Approved')):x.connection_status==='online'?' · '+esc(tr('بانتظار الاعتماد','Awaiting approval')):''}</span>`,esc(printerNotes(x)),esc(datetime(x.last_seen_at)),`${x.printer_name?`<button data-action="test-printer" data-id="${esc(x.id)}" ${x.connection_status!=='online'?'disabled':''}>${esc(tr('طباعة صفحة اختبار','Print test page'))}</button>`:''}<button class="quiet" data-action="revoke-printer" data-id="${esc(x.id)}">${esc(tr('إلغاء الربط','Disconnect'))}</button>`]))+`</section>`;}
  async function printers(){await loadBranches();const d=await api('/api/printing/devices');heading(tr('إدارة الطابعات','Printer management'),tr('اختيار الفرع ← ربط الطابعة ← اختبار ← اعتماد','Select branch → Connect → Test → Approve'));$('#content').innerHTML=`<div class="panel"><button data-action="branch-printers">${esc(tr('إعداد طابعة فرع ومتابعة الاتصال','Branch setup and connection monitoring'))}</button>${printerRows(d.devices||[])}</div>`;}
  async function branchPrinters(branchId=null){await loadBranches();state.printerBranch=branchId;modal(tr('طابعات الفروع','Branch printers'),`<div class="stack"><p>${esc(tr('١. اختر الفرع  ٢. اربط الطابعة  ٣. اطبع اختبارًا  ٤. اعتمد','1. Select branch  2. Connect printer  3. Print test  4. Approve'))}</p><label>${esc(tr('الفرع','Branch'))}<select id="printer-branch"><option value="">${esc(tr('كل الفروع','All branches'))}</option>${selectOptions(state.branches,branchId||'',b=>branchLabel(b))}</select></label><button data-action="pair-printer">${esc(tr('إعداد ربط جديد','Set up new connection'))}</button><div id="printer-live">${esc(tr('جاري تحديث الحالة…','Updating status…'))}</div></div>`);$('#printer-branch').addEventListener('change',e=>branchPrinters(e.target.value||null));const root=$('#printer-live');let busy=false;async function refresh(){if(busy||!root.isConnected||!$('#modal').open)return;busy=true;try{const [d,j]=await Promise.all([api('/api/printing/devices'),api('/api/printing/jobs')]);if(!root.isConnected)return;root.innerHTML=printerRows(d.devices||[],branchId)+table([tr('اختبار الطابعة','Printer test'),tr('الحالة','Status'),tr('الاعتماد','Approval')],(j.jobs||[]).filter(x=>x.kind==='test'&&(!branchId||x.branch_id===branchId)&&(d.devices||[]).some(v=>v.id===x.device_id&&v.acceptance_job_id===x.id&&!v.revoked_at&&!v.approved_at)).map(x=>[esc(branchLabel(x.branch_id)),esc(printStatus(x.status)),x.status==='submitted'?`<button data-action="approve-printer" data-id="${esc(x.device_id)}" data-job="${esc(x.id)}">${esc(tr('خرجت الورقة — اعتماد ✓','Paper printed — approve ✓'))}</button>`:esc(tr('بانتظار نتيجة الاختبار','Awaiting test result'))]))+table([tr('وقت الإرسال','Requested'),tr('الفرع','Branch'),tr('الفاتورة','Receipt'),tr('الحالة','Status')],(j.jobs||[]).filter(x=>x.kind!=='test'&&(!branchId||x.branch_id===branchId)).map(x=>[esc(datetime(x.created_at)),esc(branchLabel(x.branch_id)),esc(x.kind==='order'?tr('طلب','Order'):tr('تحضير','Preparation')),esc(printStatus(x.status))+(x.order_id&&['owner','delivery_manager'].includes(state.user.role)?` <button data-action="order-detail" data-id="${esc(x.order_id)}">${esc(tr('فتح الطلب / إعادة الطباعة','Open order / reprint'))}</button>`:'')]));}catch(e){if(root.isConnected)root.textContent=e.message;}finally{busy=false;}}await refresh();printerRefresh=setInterval(refresh,5000);}
  async function pairPrinter(){await loadBranches();const selected=state.printerBranch||'';modal(tr('ربط طابعة فرع','Connect branch printer'),`<form><label>${esc(tr('الفرع','Branch'))}<select name="branch_id" required><option value="">${esc(tr('اختر الفرع أولاً','Select branch first'))}</option>${selectOptions(state.branches,selected,b=>branchLabel(b))}</select></label>${field(tr('اسم الكمبيوتر','Computer name'),'label','',{required:true})}${field(tr('سبب الربط أو التعديل','Setup reason'),'reason',tr('إعداد طابعة الفرع','Branch printer setup'),{required:true})}<label>${esc(tr('عرض الورق','Paper width'))}<select name="paper_mm"><option value="80">80 mm</option><option value="58">58 mm</option></select></label>${notice(tr('نزّل الإعداد على كمبيوتر الفرع. فك الضغط وافتح Start.cmd، ثم اختر الطابعة من القائمة واضغط ربط. الملف صالح لعشر دقائق ولمرة واحدة.','Download on the branch computer. Extract, open Start.cmd, select a printer and connect. Valid for ten minutes and one use.'))}${formEnd(tr('تنزيل إعداد الفرع','Download branch setup'))}</form>`,async fd=>{const branch=fd.get('branch_id');const d=await api('/api/printing/setup',{method:'POST',body:{branch_id:branch,label:fd.get('label'),reason:fd.get('reason'),paper_mm:Number(fd.get('paper_mm'))}});const bytes=Uint8Array.from(atob(d.bundle),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:'application/zip'}));const a=document.createElement('a');a.href=url;a.download='KPS-Branch-Setup.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);await branchPrinters(branch);setStatus(tr('تم تنزيل الإعداد: فك الضغط على كمبيوتر الفرع وافتح Start.cmd.','Setup downloaded: extract on the branch computer and open Start.cmd.'));});}

  async function remotePrint(id){const o=state.orders.find(x=>x.id===id);if(!o)throw new Error(tr('حدّث الطلب أولًا.','Refresh the order first.'));const d=await api('/api/printing/devices?order_id='+encodeURIComponent(id));const devices=(d.devices||[]).filter(x=>!x.revoked_at&&x.printer_name&&x.approved_at);if(!devices.length){modal(tr('الطابعة غير مربوطة','Printer not paired'),`<p>${esc(tr('لا توجد طابعة معتمدة ضمن محافظة الطلب وصلاحياتك. اربط طابعة الفرع واختبرها أولًا.','No approved printer is available in the order city and your scope. Pair and test a branch printer first.'))}</p><button data-action="branch-printers">${esc(tr('طابعات الفروع','Branch printers'))}</button>`);return;}modal(tr('طباعة في الفرع','Print at branch'),`<form><label>${esc(tr('طابعة الفرع','Branch printer'))}<select name="device_id" required><option value="" ${devices.some(x=>x.branch_id===o.branch_id)?'':'selected'} disabled>${esc(tr('اختر فرع الطباعة','Choose print branch'))}</option>${selectOptions(devices,devices.find(x=>x.branch_id===o.branch_id)?.id||'',x=>branchLabel(x.branch_id)+' / '+x.label+' / '+x.printer_name)}</select></label><label>${esc(tr('نوع الفاتورة','Receipt type'))}<select name="kind"><option value="both">${esc(tr('فاتورة الطلب ثم التحضير','Order receipt then preparation'))}</option><option value="order">${esc(tr('فاتورة طلب','Order receipt'))}</option><option value="preparation">${esc(tr('فاتورة تحضير','Preparation receipt'))}</option></select></label><label>${esc(tr('اللغة','Language'))}<select name="language"><option value="en" selected>English</option><option value="ar">العربية</option></select></label>${textarea(tr('سبب إعادة الطباعة — عند الإعادة فقط','Reprint reason — only for a reprint'),'reprint_reason','')}${notice(tr('الافتراضي فرع الطلب؛ تظهر فقط طابعات الفروع ضمن محافظة الطلب. هذا يغيّر وجهة الطباعة فقط وليس فرع تنفيذ الطلب. عند الشك راجع الطابعة قبل الإعادة.','Defaults to the order branch. Only printers in the order city are available. Another printer changes only the print destination, not the fulfillment branch. Check the printer before reprinting.'))}${formEnd(tr('إرسال للطباعة في الفرع','Send to branch printer'))}</form>`,async fd=>{const result=await mutation('/api/printing/orders/'+encodeURIComponent(id),Object.fromEntries(fd));closeModal();setStatus(printStatus(result.status));});}
  function orderCard(o) {
    // Remote printing is separate from preparation and never changes order state.
    const prep = o.preparation_status || o.prep_status || o.status; const service = o.service || o.service_type; const id = o.id; const temporaryDelivery = service==='delivery' && o.snapshot?.delivery_workflow==='manager_dispatch'; const canPrep = !temporaryDelivery && (isAdmin() || ['branch_manager'].includes(state.user.role)); let actions = '';
    if (canPrep && !['cancelled','completed','rejected'].includes(o.status)) { const next = { new: ['accepted', tr('قبول الطلب', 'Accept order')], accepted: ['preparing', tr('بدء التجهيز', 'Start preparing')], preparing: ['ready', tr('جاهز', 'Mark ready')], ready: [service==='delivery'?'handed_over':'completed', service==='delivery'?tr('تسليم للسائق','Hand over to driver'):tr('تسليم للعميل بعد التحصيل','Complete paid customer handover')] }[prep]; if (next) actions += `<button class="small" data-action="prepare" data-id="${esc(id)}" data-status="${next[0]}">${esc(next[1])}</button>`; if (prep === 'new') actions += `<button class="quiet small" data-action="reject" data-id="${esc(id)}">${esc(tr('رفض بسبب', 'Reject with reason'))}</button>`; if (service !== 'delivery' && ['ready','handed_over'].includes(prep) && o.payment_status !== 'paid') actions += `<button class="small" data-action="collect" data-id="${esc(id)}" data-total="${esc(o.total_halalas)}">${esc(tr('تسجيل التحصيل', 'Record collection'))}</button>`; }
    if (isManager() && can('delivery_assign') && service === 'delivery' && !['completed','cancelled','rejected'].includes(prep) && !['delivered','cancelled'].includes(o.delivery_status)) actions += `<button class="quiet small" data-action="assign" data-id="${esc(id)}">${esc(o.driver_shift_id ? tr('إعادة الإسناد', 'Reassign') : tr('قبول وإسناد', 'Accept and assign'))}</button>`;
    if(['owner','delivery_manager'].includes(state.user.role)&&!(canPrep&&prep==='new')&&can('orders_cancel')&&service==='delivery'&&['new','accepted','preparing','ready'].includes(prep)&&o.delivery_status==='pending'&&['unpaid','refunded'].includes(o.payment_status))actions+=`<button class="quiet small" data-action="reject" data-id="${esc(id)}">${esc(tr('رفض مع السبب','Reject with reason'))}</button>`;
    if(['owner','delivery_manager'].includes(state.user.role))actions+=`<button class="quiet small" data-action="order-support" data-id="${esc(id)}">${esc(tr('تذاكر المتابعة والصور','Tickets and photos'))}</button><button class="quiet small" data-action="remote-print" data-id="${esc(id)}">${esc(tr('طباعة في الفرع','Print at branch'))}</button>`;
    if(['owner','delivery_manager'].includes(state.user.role)&&['paid','partially_refunded'].includes(o.payment_status))actions+=`<button class="quiet small" data-action="refund-order" data-id="${esc(id)}">${esc(tr('استرداد مأذون','Authorized refund'))}</button>`;return `<article class="panel order-detail-card"><div class="card-head"><div><h3>${esc(orderLabel(o))}</h3><span class="muted small-text">${esc(datetime(o.created_at))}</span></div>${badge(prep)}</div><div class="card-meta"><span class="pill">${esc(serviceName(service))}</span><span>${esc(branchLabel(o))}</span>${o.arrival_at || o.car_arrived_at || o.arrived_at ? `<span class="pill warn">${esc(tr('وصلت السيارة', 'Car arrived'))} ${esc(datetime(o.arrival_at || o.car_arrived_at || o.arrived_at))}</span>` : ''}${badge(o.payment_status || 'unpaid')}</div>${o.identity_kind==='guest'||o.customer_identity?.identity_kind==='guest'||o.customer?.identity_kind==='guest'?`<span class="pill warn">${esc(tr('ضيف — الجوال غير موثق','Guest — phone unverified'))}</span>`:''}${o.customer?.risk_alert?notice(tr('طلب مشابه من رقم غير موثق. راجع سياقه دون كشف طلبات العملاء الآخرين.','Similar request from an unverified contact. Review without exposing other customers.'),'warn'):''}${o.customer?.requires_operational_confirmation?`<div class="actions"><button class="quiet" data-action="operational-confirmation" data-id="${esc(id)}">${esc(tr('تسجيل نتيجة الاتصال التشغيلي','Record operational call outcome'))}</button></div>`:''}${temporaryDelivery?notice(tr('تشغيل مؤقت: المدير يسند والسائق يؤكد الاستلام؛ لا يلزم إجراء من الفرع.','Temporary workflow: manager dispatches, driver confirms pickup; no branch action required.')):''}${orderItems(o)}${o.notes ? notice(o.notes) : ''}${o.car ? `<p class="small-text">${esc(tr('السيارة', 'Car'))}: ${esc(typeof o.car === 'string' ? o.car : Object.values(o.car).join(' · '))}</p>` : ''}<dl class="data-grid">${dataItem(tr('إجمالي الطلب', 'Order total'), money(o.total_halalas))}${dataItem(tr('رسوم التوصيل', 'Delivery fee'), money(o.delivery_fee_halalas))}</dl><div class="actions">${actions}<button class="quiet small" data-action="print-order" data-id="${esc(id)}">${esc(tr('فاتورة طلب', 'Order receipt'))}</button><button class="quiet small" data-action="print-preparation" data-id="${esc(id)}">${esc(tr('فاتورة تحضير الطلب', 'Preparation receipt'))}</button></div></article>`;
  }
  function orderFilters(){return `<label>${esc(tr('الترتيب','Sort'))}<select name="sort">${[['active_oldest',tr('النشط الأقدم أولًا','Oldest active first')],['newest',tr('الأحدث أولًا','Newest first')],['oldest',tr('الأقدم أولًا','Oldest first')]].map(([v,l])=>`<option value="${v}" ${state.filters.sort===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label>${field(tr('بحث برقم الطلب','Order number'),'search',state.filters.search||'')}${field(tr('الحي','Neighborhood'),'neighborhood',state.filters.neighborhood||'')}<label>${esc(tr('الحالة','Status'))}<select name="status"><option value="">${esc(tr('كل الحالات','All statuses'))}</option>${['new','accepted','preparing','ready','completed','cancelled'].map(v=>`<option value="${v}" ${state.filters.status===v?'selected':''}>${esc(statusName(v))}</option>`).join('')}</select></label><label>${esc(tr('السائق','Driver'))}<select name="driver_id"><option value="">${esc(tr('كل السائقين المسموحين','All permitted drivers'))}</option>${selectOptions(state.drivers||[],state.filters.driver_id,x=>x.display_name)}</select></label>`;}
  function duration(t){if(!t||t.seconds==null)return esc(t?.state==='not_applicable'?tr('لا ينطبق','Not applicable'):t?.state==='cancelled'?tr('مستبعد','Excluded'):t?.state==='missing'?tr('بيانات الزمن ناقصة','Timing incomplete'):tr('لم يبدأ','Not started'));const seconds=Math.max(0,Math.floor(Number(t.seconds)));return `${num(Math.floor(seconds/60))}:${String(seconds%60).padStart(2,'0')}${t.state==='running'?` · ${esc(tr('جارٍ','Running'))}`:''}`;}
