  async function custody() { heading(tr('استلام وتسليم النقد', 'Cash receipts and handovers'), tr('يسجل مرسل النقد التسليم، ويؤكد المستلم الحقيقي الاستلام من حسابه. لا ينشأ إيراد جديد.', 'The sender records a handover and the actual recipient confirms receipt from their own account. No new revenue is created.'), state.user.role==='branch_manager'?'':`<button data-action="new-custody">${esc(tr('تسجيل تسليم', 'Record handover'))}</button>`); const d = await api('/api/custody'); $('#content').innerHTML = (d.transfers || d.events || d.custody_events || []).length ? `<div class="grid">${(d.transfers || d.events || d.custody_events).map(x=>`<article class="panel"><div class="card-head"><h3>${esc(money(x.amount_halalas))}</h3>${badge(x.status||'pending')}</div><p>${esc(x.reference)}</p><p class="muted small-text">${esc(datetime(x.created_at))}</p><dl class="data-grid">${dataItem(tr('من شفت','From shift'),shiftLabel(x.from_shift_id))}${dataItem(tr('إلى المستلم','To recipient'),x.recipient_name||x.recipient_user_id||x.to_shift_id)}</dl>${x.status==='pending' && x.recipient_user_id===state.user.id ? `<button data-action="confirm-custody" data-id="${esc(x.id)}">${esc(tr('تأكيد استلام النقد الفعلي','Confirm actual cash receipt'))}</button>` : ''}</article>`).join('')}</div>` : empty(tr('لا توجد تسليمات نقدية ضمن نطاقك.', 'No cash handovers in your scope.')); }
  function conversationLabel(c) { return c.order_reference||c.order_no||tr('محادثة مرتبطة بطلب','Order conversation'); }
