  let inboxPolling=false;
  async function pollInbox(){
    const root=$('.conversation-list'),user=state.user?.id;
    if(inboxPolling||state.page!=='chat'||!root)return;
    inboxPolling=true;
    try{const d=await api('/api/conversations');if(state.page!=='chat'||root!==$('.conversation-list')||state.user?.id!==user)return;const rows=d.conversations||[],signature=JSON.stringify([rows,state.selectedConversation,state.lang]);if(root.dataset.signature===signature||root.contains(document.activeElement))return;const top=root.scrollTop;root.innerHTML=rows.map(c=>`<button class="conversation ${c.id===state.selectedConversation?'active':''}" data-action="conversation" data-id="${esc(c.id)}"><strong>${esc(conversationLabel(c))}</strong><small>${esc(c.last_message||c.last_message_text||'')}</small><div class="card-meta">${badge(c.status||'open')}<span class="pill">${esc(c.route==='delivery'?tr('التوصيل','Delivery'):tr('الفرع','Branch'))}</span>${c.unread_count?`<span class="pill warn">${esc(num(c.unread_count))} ${esc(tr('غير مقروءة','unread'))}</span>`:''}</div></button>`).join('')||empty(tr('لا توجد محادثات.','No conversations.'));root.dataset.signature=signature;root.scrollTop=top;state.conversations=rows;}catch{}finally{inboxPolling=false;}
  }
  let conversationPolling=false;
  async function pollConversation(){
    const root=$('#chat-detail'),id=state.selectedConversation,version=conversationVersion;
    if(conversationPolling||state.page!=='chat'||!id||root?.dataset.conversation!==id)return;
    conversationPolling=true;
    try{
      const previous=state.chatHistory.get(id)||[],after=previous.at(-1)?.seq||0;
      const d=await api(`/api/conversations/${encodeURIComponent(id)}/messages?after=${after}`);
      if(state.page!=='chat'||state.selectedConversation!==id||version!==conversationVersion||root!==$('#chat-detail'))return;
      const box=$('#messages',root);if(!box)return;const error=$('.form-error',root);if(error?.dataset.pollFailed){error.textContent='';delete error.dataset.pollFailed;}
      const bottom=box.scrollHeight-box.scrollTop-box.clientHeight<60,top=box.scrollTop;
      const rows=d.messages||[],fresh=rows.filter(m=>!previous.some(p=>p.id===m.id));
      if(fresh.length){if(!previous.length)box.replaceChildren();box.insertAdjacentHTML('beforeend',fresh.map(messageMarkup).join(''));state.chatHistory.set(id,[...previous,...fresh]);box.scrollTop=bottom?box.scrollHeight:top;}
      const more=$('[data-action="more-messages"]',root);
      if(more){more.dataset.after=String((state.chatHistory.get(id)||[]).at(-1)?.seq||after);if(rows.length<100)more.remove();}
      const seq=(state.chatHistory.get(id)||[]).at(-1)?.seq;
      if(bottom&&seq&&root.dataset.readSeq!==String(seq)){await api(`/api/conversations/${encodeURIComponent(id)}/read`,{method:'POST',body:{through_seq:seq}});if(root.isConnected)root.dataset.readSeq=String(seq);}
    }catch(e){if(root?.isConnected&&state.page==='chat'){const error=$('.form-error',root);if(error&&!error.textContent){error.textContent=tr('تعذر تحديث الرسائل مؤقتًا؛ ستتم إعادة المحاولة تلقائيًا.','Messages could not refresh; retrying automatically.');error.dataset.pollFailed='true';}}}finally{conversationPolling=false;}
  }

  async function imageUpload(path,file,extra={}) { if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw new Error(tr('اختر صورة JPEG أو PNG أو WebP لا تتجاوز 5 MB.','Choose a JPEG, PNG or WebP image up to 5 MB.')); const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(new Error(tr('تعذر قراءة الصورة.','Could not read the image.')));r.readAsDataURL(file);});return mutation(path,{...extra,data_base64:data,content_type:file.type}); }

  function photoTransition(id,stage){let photoId=null;modal(tr(stage==='picked_up'?'صورة الاستلام من الفرع':'صورة تسليم الطلب',stage==='picked_up'?'Branch pickup photo':'Delivery photo'),`<form><label>${esc(tr('صورة إلزامية — الطلب فقط، تجنب تصوير الأشخاص','Required photo — photograph the order, avoid people'))}<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" capture="environment" required></label>${textarea(tr('ملاحظة اختيارية','Optional note'),'proof','')}${formEnd(tr('حفظ الصورة وتأكيد الخطوة','Save photo and confirm'))}</form>`,async(fd)=>{const file=fd.get('photo');if(!photoId){if(!file?.size)throw new Error(tr('أضف الصورة أولاً','Add a photo first'));photoId=(await imageUpload(`/api/tasks/${encodeURIComponent(id)}/photos`,file,{stage})).id;}await mutation(`/api/tasks/${encodeURIComponent(id)}/transition`,{status:stage,photo_id:photoId,proof:fd.get('proof')||''});closeModal();await loadPage();});$('#modal-body input[type=file]').addEventListener('change',()=>{photoId=null;});}
  function supportTable(d){return table([tr('التذكرة / الطلب','Ticket / order'),tr('التصنيف','Category'),tr('الحالة','Status'),tr('الملاحظة','Note'),tr('الإجراء','Action')],(d.tickets||[]).map(t=>[esc(t.reference)+'<br>'+esc(t.order_reference||t.order_id),esc(d.categories[t.category]||t.category),esc(d.states[t.status]||t.status),esc(t.note),`<button class="quiet small" data-action="support-update" data-id="${esc(t.id)}" data-order="${esc(t.order_id)}">${esc(tr('تحديث للعميل','Update customer'))}</button>`]));}
  async function support(day=state.supportDay||''){state.supportDay=day;state.page='support';navigation();heading(tr('تذاكر المتابعة والتقرير اليومي','Support tickets and daily report'),tr('التذاكر الجديدة والمحدثة والمفتوحة. التحديث يصل داخل محادثة الطلب.','New, updated and open tickets. Updates appear in the order conversation.'));const d=await api('/api/support-daily'+(day?'?day='+encodeURIComponent(day):''));$('#content').innerHTML=`<form id="support-day" class="filter-form"><label>${esc(tr('اليوم التشغيلي','Operational day'))}<input name="day" type="date" value="${esc(d.day)}" required></label><button>${esc(tr('عرض','Show'))}</button></form><dl class="data-grid">${dataItem(tr('جديدة','New'),d.summary.created)}${dataItem(tr('أغلقت','Closed'),d.summary.closed)}${dataItem(tr('مفتوحة','Open'),d.summary.open)}</dl>${notice(tr('لرفع تذكرة: افتح طلب العميل واختر تذاكر المتابعة والصور.','To create a ticket, open the customer order and choose Tickets and photos.'))}${supportTable(d)}`;$('#support-day').addEventListener('submit',async e=>{e.preventDefault();try{await support(new FormData(e.currentTarget).get('day'));}catch(x){setStatus(x.message,true);}});}
  async function orderSupport(id){const d=await api('/api/support-tickets?order_id='+encodeURIComponent(id));const photos=await api(`/api/orders/${encodeURIComponent(id)}/delivery-photos`);modal(tr('متابعة مشكلة الطلب','Order issue follow-up'),`<div class="stack">${supportTable(d)}<form><label>${esc(tr('نوع التذكرة','Ticket category'))}<select name="category">${Object.entries(d.categories).map(([v,l])=>`<option value="${esc(v)}">${esc(l)}</option>`).join('')}</select></label><label>${esc(tr('تفاصيل المشكلة — تظهر للعميل','Issue details — visible to customer'))}<textarea name="note" maxlength="2000" required></textarea></label>${formEnd(tr('رفع تذكرة وإبلاغ العميل','Create ticket and notify customer'))}</form><h3>${esc(tr('صور الاستلام والتسليم','Pickup and delivery photos'))}</h3>${photos.photos.map(p=>`<p>${esc(p.stage==='picked_up'?tr('استلام الفرع','Branch pickup'):tr('تسليم العميل','Customer delivery'))} · ${esc(datetime(p.created_at))} ${p.deleted_at?esc(tr('انتهت مدة الاحتفاظ','Retention expired')):`<a target="_blank" rel="noopener" href="/api/delivery-photos/${encodeURIComponent(p.id)}">${esc(tr('عرض الصورة','View photo'))}</a>`}</p>`).join('')}</div>`,async fd=>{const r=await mutation('/api/support-tickets',{order_id:id,category:fd.get('category'),note:fd.get('note')});await orderSupport(id);setStatus(tr('تم رفع تذكرة برقم ','Ticket created: ')+r.reference);});}
