    if(state.adminTab==='settings'){let recovery={},monitoring={};if(state.user.role==='owner'){const results=await Promise.allSettled([api('/api/admin/recovery'),api('/api/admin/monitoring')]);recovery=results[0].status==='fulfilled'?results[0].value:{status:'unavailable',read_error:results[0].reason.message};monitoring=results[1].status==='fulfilled'?results[1].value:{status:'unavailable',read_error:results[1].reason.message};}html=notice(tr('المنطقة الزمنية: توقيت الرياض (UTC+3). جميع أوقات النظام وفق هذا التوقيت.','Time zone: Riyadh (UTC+3). All system times use this time zone.'))+settingsForm(cfg)+(state.user.role==='owner'?`<button data-action="invoice-profiles">${esc(tr('المؤسسات والضريبة وQR','Entities, VAT and QR'))}</button>`:'')+`<div class="actions"><button class="quiet" data-action="identity-settings">${esc(tr('قنوات الهوية والضيف','Identity channels and guest'))}</button><button class="quiet" data-action="owner-link">${esc(tr('ربط البريد الموثق للمالك','Verify owner email'))}</button>${can('brand_services_manage')?`<button class="quiet" data-action="services">${esc(tr('خدمات البراند','Brand services'))}</button>`:''}<button class="quiet" data-action="delivery-only">${esc(tr('التوصيل فقط لفروع محددة','Delivery only for selected branches'))}</button><button class="quiet" data-action="performance-policy">${esc(tr('معايير أداء المحافظات','Province performance policies'))}</button></div>`+(state.user.role==='owner'?recoveryPanel(recovery)+monitoringPanel(monitoring):'');}if(state.adminTab==='brands')html=`<section class="panel"><h2>${esc(cfg.brand?.name)}</h2><p class="code">${esc(cfg.brand?.id)}</p><p class="muted">${esc(tr('كل براند مستقل ببياناته وموظفيه ونطاق حساب مالكه.','Each brand has separate data, staff and owner access.'))}</p><div class="actions"><button data-action="create-brand">${esc(tr('إضافة براند','Add brand'))}</button></div></section>`;
