  document.addEventListener('change',e=>{
    const picker=e.target.closest('.staff-branch-picker');if(!picker)return;
    picker.querySelector('output').textContent=picker.querySelectorAll('input[type=checkbox]:checked').length;
  });
  document.addEventListener('reset',e=>{
    if(!e.target.matches('.staff-branch-form'))return;
    const form=e.target;setTimeout(()=>{form.querySelector('output').textContent=form.querySelectorAll('input[type=checkbox]:checked').length;form.querySelector('.form-error').textContent='';form.querySelector('details').open=false;});
  });
  document.addEventListener('submit',async e=>{
    const form=e.target;if(!form.matches('.staff-branch-form'))return;e.preventDefault();
    const button=form.querySelector('button[type=submit]'),error=form.querySelector('.form-error');button.disabled=true;error.textContent='';
    try {const fd=new FormData(form);await api(`/api/identity/staff/${encodeURIComponent(form.dataset.staffId)}`,{method:'PATCH',body:{branch_ids:checkedBranches(fd,'scope'),reason:fd.get('reason')}});state.staff=null;await loadPage();setStatus(tr('تم حفظ الفروع المسندة.','Assigned branches saved.'));}
    catch(x){error.textContent=x.message;}finally{if(button.isConnected)button.disabled=false;}
  });
  function checkedBranches(fd,name) { return state.branches.filter(b=>fd.has(`${name}:${b.id}`)).map(b=>b.id); }
  function recoveryPanel(r) {
    const labels={unconfigured:tr('النسخ الاحتياطي غير مهيأ وغير متحقق منه.','Backups are unconfigured and unverified.'),unverified:tr('توجد إعدادات مزود، لكن النسخ الاحتياطي لم يُتحقق منه.','Provider settings exist, but backups are unverified.'),attention_required:tr('توجد تنبيهات فشل محفوظة تحتاج مراجعة المالك.','Persistent failure alerts require owner review.'),observed:tr('رُصد حدث من المزود؛ نجاح الاسترجاع لم يُثبت بذلك.','A provider event was observed; this does not prove a successful restore.'),unavailable:tr('تعذر قراءة حالة النسخ؛ لا توجد حالة نجاح مؤكدة.','Backup status could not be read; no success is confirmed.')};
    const unknown=tr('غير متحقق منه','Unverified'),source={none:tr('لا يوجد تحقق من المزود','No provider verification'),signed_webhook:tr('حدث مزود بتوقيع متحقق منه','Verified signed provider event'),provider_api:tr('قراءة فعلية من واجهة المزود','Actual provider API observation')}[r.verification_source]||unknown;
    const seconds=value=>value==null?unknown:`${num(value)} ${tr('ثانية','seconds')}`;
    const alerts=r.open_alerts||[];
    return `<section class="panel" id="recovery-health"><div class="card-head"><h2>${esc(tr('النسخ الاحتياطي والاستعادة','Backup and recovery'))}</h2><span class="pill warn">${esc(tr('الاسترجاع يحتاج إثباتًا مستقلًا','Restore needs independent verification'))}</span></div>${notice(labels[r.status]||labels.unavailable,'warn')}${r.read_error?notice(r.read_error,'error'):''}${alerts.map(alert=>`<div class="notice error recovery-alert" role="alert"><strong>${esc(tr('تنبيه فشل محفوظ لم يُراجع','Persistent failure alert awaiting review'))}</strong><p>${esc(datetime(alert.created_at))}</p><button type="button" class="quiet small" data-action="ack-recovery-alert" data-id="${esc(alert.id)}">${esc(tr('الإقرار بمراجعة التنبيه','Acknowledge alert review'))}</button></div>`).join('')}<dl class="data-grid">${dataItem(tr('آخر نجاح مرصود','Last observed success'),r.last_success_at?datetime(r.last_success_at):unknown)}${dataItem(tr('آخر فشل محفوظ','Last recorded failure'),r.last_failure_at?datetime(r.last_failure_at):tr('لا يوجد حدث فشل مؤكد','No confirmed failure event'))}${dataItem(tr('الاحتفاظ حسب المصدر','Retention from source'),r.retention_days==null?unknown:`${num(r.retention_days)} ${tr('يوم','days')}`)}${dataItem(tr('نافذة الفقد المحتملة حسب المصدر','Potential loss window from source'),seconds(r.potential_loss_window_seconds))}${dataItem(tr('أقدم نقطة استرجاع مثبتة','Verified earliest recovery point'),r.recoverable_from?datetime(r.recoverable_from):unknown)}${dataItem(tr('أحدث نقطة استرجاع مثبتة','Verified latest recovery point'),r.recoverable_until?datetime(r.recoverable_until):unknown)}${dataItem(tr('زمن الاستعادة المقاس','Measured restore duration'),seconds(r.measured_restore_seconds))}${dataItem(tr('آخر رصد متحقق منه','Last verified observation'),r.last_verified_at?datetime(r.last_verified_at):unknown)}${dataItem(tr('آخر تجربة استعادة مثبتة','Last verified restore drill'),r.last_restore_verified_at?datetime(r.last_restore_verified_at):unknown)}</dl><p class="small-text muted">${esc(tr('مصدر الرصد','Observation source'))}: ${esc(source)}. ${esc(tr('النسخ والاسترجاع يشملان البيانات والمرفقات والتقارير. الإقرار بتنبيه لا يعني إصلاح الفشل أو نجاح تجربة الاسترجاع.','Backup and restore must include data, attachments and reports. Acknowledging an alert does not repair failure or prove a restore test.'))}</p></section>`;
  }
  function monitoringPanel(m) {
    const unknown=tr('غير متحقق منه','Unverified'),metrics=m.metrics||{},delivery=m.external_alert_delivery||{};
    const labels={unavailable:tr('تعذر قراءة المراقبة','Monitoring unavailable'),unverified:tr('لم تسجل قراءة فعلية','No actual observation yet'),stale:tr('القراءة قديمة وتحتاج تحديثًا','Observation is stale'),attention_required:tr('توجد أعطال تحتاج مراجعة','Failures need review'),observed:tr('قراءة فعلية محفوظة','Actual observation recorded')};
    const checks={runtime_server_errors:tr('أخطاء الخادم','Server errors'),runtime_database_latency:tr('بطء قاعدة البيانات','Database latency'),runtime_email_delivery_failed:tr('فشل إرسال البريد','Email send failure'),runtime_email_queue_stalled:tr('تراكم البريد المنتظر','Mail queue stalled'),runtime_backup_observation_stale:tr('عدم وجود رصد حديث للنسخ الاحتياطي','No recent backup observation'),runtime_memory_pressure:tr('ضغط الذاكرة','Memory pressure'),runtime_ephemeral_storage_pressure:tr('امتلاء التخزين المؤقت','Ephemeral storage pressure'),runtime_database_storage_pressure:tr('امتلاء تخزين قاعدة البيانات','Database storage pressure')};
    const measurement=(value,unit='')=>value==null?unknown:num(value)+(unit?' '+unit:'');
    return `<section class="panel" id="operational-monitoring"><div class="card-head"><h2>${esc(tr('المراقبة والتنبيهات','Monitoring and alerts'))}</h2><button type="button" class="quiet small" data-action="monitoring-refresh">${esc(tr('فحص الآن','Check now'))}</button></div>${notice(labels[m.status]||labels.unverified,m.status==='attention_required'?'error':'warn')}${m.read_error?notice(m.read_error,'error'):''}${(m.failing_checks||[]).map(check=>notice(checks[check]||tr('تنبيه تشغيل محفوظ','Recorded operational alert'),'error')).join('')}<dl class="data-grid">${dataItem(tr('آخر فحص فعلي','Last actual check'),m.last_checked_at?datetime(m.last_checked_at):unknown)}${dataItem(tr('استجابة قاعدة البيانات','Database response'),measurement(metrics.database_latency_ms,tr('مللي ثانية','ms')))}${dataItem(tr('حجم قاعدة البيانات','Database size'),measurement(metrics.database_size_bytes==null?null:Math.round(metrics.database_size_bytes/1048576),tr('ميجابايت','MB')))}${dataItem(tr('البريد المنتظر','Queued mail'),measurement(metrics.mail_queued))}${dataItem(tr('فشل البريد الحديث','Recent mail failures'),measurement(metrics.mail_recently_failed))}${dataItem(tr('أخطاء الخادم المرصودة','Observed server errors'),measurement(metrics.server_errors))}${dataItem(tr('قناة التنبيه الإدارية','Administrative alert channel'),delivery.configured?tr('مهيأة — الاستلام يحتاج إثباتًا','Configured — receipt needs proof'):tr('غير مهيأة','Unconfigured'))}${dataItem(tr('استلام التنبيه في الصندوق','Alert inbox receipt'),delivery.inbox_receipt_verified?tr('مثبت فعليًا','Actually verified'):unknown)}${dataItem(tr('تنبيه التعطل من خارج الخدمة','Outage alert outside this service'),m.out_of_process_down_alert_verified?tr('مثبت فعليًا','Actually verified'):unknown)}</dl><p class="small-text muted">${esc(tr('قبول مزود البريد لا يثبت وصول التنبيه للصندوق. تعطل الخدمة الكامل يحتاج تنبيهًا يعمل خارجها.','Provider acceptance does not prove inbox receipt. A complete outage requires an alert running outside the service.'))}</p></section>`;
  }
  function appearanceForm(cfg) {
    const selected=cfg.settings?.theme?.profile||'ORIGINAL_Light';
    return `<fieldset id="appearance-settings"><legend>${esc(tr('إعدادات المظهر','Appearance'))}</legend><div class="appearance-options"><button type="button" class="quiet" data-appearance="CHARCOAL" aria-pressed="${selected==='CHARCOAL'}">${esc(tr('فحمي','Charcoal'))}</button><button type="button" class="quiet" data-appearance="ORIGINAL_Light" aria-pressed="${selected==='ORIGINAL_Light'}">${esc(tr('التصميم السابق','Previous design'))}</button></div><p class="muted">${esc(tr('التبديل محفوظ لهذا البراند ويظهر على خدمة التجربة. الموقع الرسمي يبقى على التصميم السابق حتى الاعتماد.','Saved for this brand on the test service. The official domain keeps the previous design until approval.'))}</p><p id="appearance-result" role="status" class="progress-note"></p></fieldset>`;
  }
  function bindAppearance() {
    document.querySelectorAll('[data-appearance]').forEach(button=>button.addEventListener('click',async()=>{
      const buttons=[...document.querySelectorAll('[data-appearance]')];
      buttons.forEach(b=>b.disabled=true);
      try {
        const result=await api('/api/admin/settings',{method:'PATCH',body:{theme:{profile:button.dataset.appearance}}});
        state.config.settings=result.settings;
        window.KPSAppearance?.saved(result.settings.theme,state.user.brand_id);
        buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.appearance===result.settings.theme.profile)));
        $('#appearance-result').textContent=tr('تم حفظ المظهر. يمكنك الرجوع فورًا من التصميم السابق.','Appearance saved. Previous design restores it immediately.');
      } catch(error) { $('#appearance-result').textContent=error.message; }
      finally { buttons.forEach(b=>b.disabled=false); }
    }));
  }
  function settingsForm(cfg) { if(state.user.role==='admin')return `<section class="panel">${appearanceForm(cfg)}<button class="quiet" data-action="presentation-settings">${esc(tr('الشريط المتحرك والعبارة الأدبية','Moving strip & literary phrase'))}</button></section>`;const s=cfg.settings||{},theme=s.theme||{}; return `<section class="panel"><h2>${esc(tr('إعدادات التشغيل والهوية','Operating settings and appearance'))}</h2>${appearanceForm(cfg)}${notice(cfg.otp_configured?tr('مزود تحقق الجوال مهيأ. يظل الإطلاق مشروطًا باختبار الإرسال الحقيقي.','Phone verification provider is configured. Launch still requires a real delivery test.'):tr('مزود تحقق الجوال غير مهيأ. الطلب كضيف يعمل بصورة مستقلة بحسب إعداد القناة.','Phone verification is unconfigured. Guest ordering operates independently under its channel policy.'),cfg.otp_configured?'':'warn')}<form id="settings-form" class="form-columns" style="margin-top:18px"><label>${esc(tr('مسار طلبات التوصيل الجديدة','Workflow for new delivery orders'))}<select name="delivery_workflow"><option value="manager_dispatch" ${s.delivery_workflow==='manager_dispatch'?'selected':''}>${esc(tr('مؤقت — إسناد المدير واستلام السائق دون إجراء الفرع','Temporary — manager dispatch and driver pickup without branch action'))}</option><option value="branch_fulfillment" ${s.delivery_workflow!=='manager_dispatch'?'selected':''}>${esc(tr('كامل — تجهيز الفرع وتسليمه للسائق','Full — branch preparation and handover'))}</option></select></label><p class="small-text">${esc(tr('يسري على الطلبات الجديدة؛ الطلبات القائمة تحتفظ بمسارها. تذكرة الطباعة متاحة، والطباعة الآلية تتطلب ربط الطابعة واختباره.','Applies to new orders; existing orders keep their workflow. Print tickets are available; automatic printing requires printer setup and testing.'))}</p>${field(tr('بداية اليوم التشغيلي','Operational day start'),'day_start',s.operational_day_start||'',{type:'time',required:true})}${field(tr('تنبيه عمر الطلب الجاري بالدقائق — مستقل عن معيار الطريق','Live order age alert (minutes) — separate from road policy'),'late_after',s.late_after_minutes??'',{type:'number',min:1,required:true})}${field(tr('اتصال تشغيلي لطلب ضيف أعلى من — ريال، فارغ دون شرط','Guest call above amount — SAR; blank for no threshold'),'guest_call_above',s.guest_operational_confirmation_above_halalas==null?'':moneyInput(s.guest_operational_confirmation_above_halalas),{type:'number',min:0,step:'.01'})}${field(tr('لون الإجراء','Action color'),'accent',theme.accent||'#a94710',{type:'color'})}${field(tr('الخلفية','Background'),'background',theme.background||'#f7f8f6',{type:'color'})}${field(tr('النص','Text color'),'text',theme.text||'#1d2826',{type:'color'})}<label>${esc(tr('الخط','Font'))}<select name="font">${['Noto Kufi Arabic'].map(f=>`<option ${theme.font===f?'selected':''}>${f}</option>`).join('')}</select></label>${formEnd(tr('حفظ الإعدادات','Save settings'))}</form><p class="progress-note">${esc(tr('ساعات استقبال الطلبات إعداد مستقل لكل فرع. حفظ المظهر لا يغيّر قواعد الطلب والتسعير.','Order acceptance hours are configured separately for each branch. Appearance does not affect order or pricing rules.'))}</p></section>`; }
  function hoursEditor(name,value) { return `<fieldset class="full"><legend>${esc(name==='opening_hours'?tr('ساعات استقبال الطلبات','Order hours'):tr('ساعات التوصيل','Delivery hours'))}</legend><div id="${name}-rows" class="stack">${(value||[]).map((row,i)=>hoursRow(name,row,i)).join('')}</div><div class="actions"><button type="button" class="quiet small" data-action="add-hours" data-name="${name}">${esc(tr('إضافة فترة','Add hours interval'))}</button></div></fieldset>`; }
  function hoursRow(name,row={},index=Date.now()) { const days=[tr('الاثنين','Monday'),tr('الثلاثاء','Tuesday'),tr('الأربعاء','Wednesday'),tr('الخميس','Thursday'),tr('الجمعة','Friday'),tr('السبت','Saturday'),tr('الأحد','Sunday')]; return `<div class="hours-row" data-name="${name}" data-index="${index}"><div class="form-columns">${field(tr('من','From'),`${name}_start_${index}`,row.start||'',{type:'time',required:true})}${field(tr('إلى','Until'),`${name}_end_${index}`,row.end||'',{type:'time',required:true})}</div><div class="actions">${days.map((d,n)=>check(d,`${name}_day_${index}_${n}`,row.days?.includes(n))).join('')}<button type="button" class="quiet small" data-action="remove-hours">${esc(tr('إزالة الفترة','Remove interval'))}</button></div></div>`; }
  function getHours(fd,form,name) { return [...form.querySelectorAll(`.hours-row[data-name="${name}"]`)].map(row=>{const i=row.dataset.index; const days=Array.from({length:7},(_,n)=>n).filter(n=>fd.has(`${name}_day_${i}_${n}`));if(!days.length)throw new Error(tr('حدد أيام العمل لكل فترة.','Select operating days for every interval.'));return{days,start:fd.get(`${name}_start_${i}`),end:fd.get(`${name}_end_${i}`)};}); }
  function editBranch(id) { const b=state.config.branches.find(x=>x.id===id);const s=b.settings||{};const c=s.coverage||{};modal(tr('إعداد الفرع والتغطية','Branch and coverage configuration'),`<form class="form-columns">${notice(tr('تستخدم هذه البيانات للطلبات الجديدة فقط. لا تغيّر رقم الفرع أو تضع دبوسًا أو رسومًا غير مؤكدة.','These settings affect new orders only. Do not renumber the branch or enter unverified location or fees.'),'warn')}${field(tr('رقم الفرع التشغيلي — ثابت','Operating branch number — immutable'),'branch_no',b.branch_no,{readonly:true})}${field(tr('معرّف قاعدة البيانات — ثابت','Database ID — immutable'),'branch_id',b.id,{readonly:true})}${field(tr('اسم الفرع','Branch name'),'name',b.name,{required:true})}${field(tr('المدينة الفعلية','Actual city'),'city',b.city,{required:true})}${check(tr('الفرع يستقبل طلبات جديدة','Accept new orders'),'active',s.active!==false)}${check(tr('اعتماد بيانات التشغيل الصحيحة','Verify actual operating data'),'ordering_verified',s.ordering_verified===true)}${check(tr('استلام من الفرع','Branch pickup'),'pickup_enabled',s.pickup_enabled)}${check(tr('استلام بالسيارة','Car pickup'),'car_enabled',s.car_enabled)}${check(tr('توصيل ضمن المدن الست','Delivery within approved six cities'),'delivery_enabled',s.delivery_enabled)}${check(tr('كاش عند الاستلام','Cash on receipt'),'cash',s.payment_methods?.includes('cash'))}${check(tr('شبكة عند الاستلام','Card on receipt'),'card',s.payment_methods?.includes('card'))}${hoursEditor('opening_hours',s.opening_hours)}${hoursEditor('delivery_hours',s.delivery_hours)}${field(tr('خط العرض الفعلي للفرع','Actual branch latitude'),'lat',s.location?.lat??'',{type:'number',step:'any'})}${field(tr('خط الطول الفعلي للفرع','Actual branch longitude'),'lng',s.location?.lng??'',{type:'number',step:'any'})}${check(tr('دبوس الفرع مطابق ومتحقق من المصدر','Branch pin matches verified source'),'location_verified',s.location_verified===true||(s.location_verified===undefined&&s.ordering_verified===true))}${field(tr('رابط Google Maps المعتمد — بديل عند نقص الدبوس','Approved Google Maps URL — fallback if pin unavailable'),'map_url',s.map_url||'',{dir:'ltr',full:true})}${field(tr('معرف Google Place ID — اختياري','Google Place ID — optional'),'place_id',s.place_id||'',{dir:'ltr',full:true})}${field(tr('مصدر التحقق من الموقع — رابط أو وصف الدليل','Location verification source — link or evidence'),'location_source',s.location_source||'',{full:true,maxlength:1000})}${check(tr('رابط الموقع ومعرف المكان معتمدان لهذا الفرع','Map URL and Place ID approved for this branch'),'map_url_verified',s.map_url_verified===true)}${field(tr('رسوم التوصيل — ريال، اتركها فارغة إن لم تعتمد','Delivery fee — SAR; blank if unverified'),'fee',s.delivery_fee_halalas==null?'':moneyInput(s.delivery_fee_halalas),{type:'number',min:0,step:'.01'})}${field(tr('الحد الأدنى للتوصيل — ريال','Delivery minimum — SAR'),'minimum',s.minimum_order_halalas==null?'':moneyInput(s.minimum_order_halalas),{type:'number',min:0,step:'.01'})}<label class="full">${esc(tr('نطاق التوصيل المعتمد','Approved delivery coverage'))}<select name="coverage_type"><option value="">${esc(tr('غير مهيأ — التوصيل محجوب','Unconfigured — delivery blocked'))}</option><option value="radius" ${c.type==='radius'?'selected':''}>${esc(tr('دائرة خدمة فعلية معتمدة','Verified service radius'))}</option><option value="polygon" ${c.type==='polygon'?'selected':''}>${esc(tr('مضلع خدمة فعلي معتمد','Verified coverage polygon'))}</option></select></label>${field(tr('خط عرض مركز التغطية','Coverage center latitude'),'center_lat',c.center?.lat??'',{type:'number',step:'any'})}${field(tr('خط طول مركز التغطية','Coverage center longitude'),'center_lng',c.center?.lng??'',{type:'number',step:'any'})}${field(tr('نصف القطر المعتمد بالمتر','Approved radius in meters'),'radius',c.radius_meters??'',{type:'number',min:1})}${textarea(tr('نقاط المضلع: خط الطول،خط العرض لكل سطر','Polygon points: longitude,latitude per line'),'polygon',(c.coordinates||[]).map(x=>x.join(',')).join('\n'))}${formEnd(tr('حفظ بيانات الفرع','Save branch configuration'))}</form>`,async(fd,form)=>{const settings={active:fd.has('active'),ordering_verified:fd.has('ordering_verified'),pickup_enabled:fd.has('pickup_enabled'),car_enabled:fd.has('car_enabled'),delivery_enabled:fd.has('delivery_enabled'),location_verified:fd.has('location_verified'),map_url_verified:fd.has('map_url_verified'),map_url:String(fd.get('map_url')||'').trim()||null,place_id:String(fd.get('place_id')||'').trim()||null,location_source:String(fd.get('location_source')||'').trim()||null,payment_methods:['cash','card'].filter(k=>fd.has(k)),opening_hours:getHours(fd,form,'opening_hours'),delivery_hours:getHours(fd,form,'delivery_hours'),location:null,coverage:null,delivery_fee_halalas:fd.get('fee')===''?null:cents(fd.get('fee')),minimum_order_halalas:fd.get('minimum')===''?null:cents(fd.get('minimum'))};if(fd.get('lat')!==''||fd.get('lng')!==''){if(fd.get('lat')===''||fd.get('lng')==='')throw new Error(tr('أدخل خط العرض والطول معًا، أو امسحهما معًا لإزالة الدبوس.','Enter both coordinates, or clear both to remove the pin.'));settings.location={lat:Number(fd.get('lat')),lng:Number(fd.get('lng'))};}if(!settings.location)settings.location_verified=false;if(!settings.map_url&&!settings.place_id)settings.map_url_verified=false;const type=fd.get('coverage_type');if(type==='radius'){if([fd.get('center_lat'),fd.get('center_lng'),fd.get('radius')].some(v=>v===''))throw new Error(tr('أكمل موقع مركز التغطية ونصف القطر المعتمد.','Complete the verified coverage center and radius.'));settings.coverage={type,center:{lat:Number(fd.get('center_lat')),lng:Number(fd.get('center_lng'))},radius_meters:Number(fd.get('radius'))};}if(type==='polygon'){const coordinates=String(fd.get('polygon')).trim().split(/\n/).map(row=>row.split(',').map(Number));if(coordinates.length<3||coordinates.some(x=>x.length!==2||x.some(n=>!Number.isFinite(n))))throw new Error(tr('أدخل ثلاث نقاط مضلع صحيحة على الأقل.','Enter at least three valid polygon points.'));settings.coverage={type,coordinates};}await api(`/api/admin/branches/${encodeURIComponent(id)}`,{method:'PATCH',body:{name:fd.get('name'),city:fd.get('city'),settings}});closeModal();await loadPage();}); }
  function optionGroupEditor(groups) { return `<fieldset class="full"><legend>${esc(tr('المقاسات / الألوان / النكهات','Sizes / colors / flavors'))}</legend><div id="option-groups" class="stack">${groups.map((g,i)=>optionGroup(g,i)).join('')}</div><div class="actions"><button type="button" class="quiet small" data-action="add-option-group">${esc(tr('إضافة مجموعة خيارات','Add option group'))}</button></div></fieldset>`; }
