        document.getElementById('invoice-preview-'+key).innerHTML=`<section style="max-width:300px;background:white;color:black;padding:12px;margin:12px auto;border:1px solid">
          <h2>KPS COFFEE</h2><strong>${esc(entity.vat_enabled?'مسودة فاتورة ضريبية مبسطة / Tax invoice DRAFT':'معاينة فاتورة بيع / Sales receipt PREVIEW')}</strong>
          ${entity.vat_enabled?`<p>VAT: ${esc(entity.vat_number)}</p><p>${esc(tr('قبل الضريبة','Before VAT'))}: ${(p.net_halalas/100).toFixed(2)}</p><p>VAT 15%: ${(p.tax_halalas/100).toFixed(2)}</p>`:''}
          <p><strong>TOTAL: SAR 23.00</strong></p><img alt="Preview QR" src="${esc(p.qr_image)}" style="width:100%;height:auto;aspect-ratio:1">
          <p>${esc(tr('معاينة فقط — ليست فاتورة فعلية أو رمز زاتكا','Preview only — not an actual invoice or ZATCA QR'))}</p></section>`;
