  function receiptHTML(o, preparation=false,receiptLanguage='en') {
    const tr=(ar,en)=>receiptLanguage==='ar'?ar:en;
    const money=v=>new Intl.NumberFormat(receiptLanguage==='ar'?'ar-SA':'en-SA',{style:'currency',currency:'SAR'}).format(Number(v||0)/100);
    const datetime=v=>new Intl.DateTimeFormat(receiptLanguage==='ar'?'ar-SA':'en-GB',{timeZone:'Asia/Riyadh',dateStyle:'short',timeStyle:'short'}).format(new Date(v));
    const title=tr(preparation?'فاتورة تحضير الطلب':'فاتورة طلب',preparation?'Preparation receipt':'Order receipt');
    const row=(label,value)=>`<div class="receipt-row"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`;
    const items=(o.items||[]).map((item,index)=>{
      const label=name=>receiptLanguage==='en'?(o.print_labels_en?.[item.product_id||'']?.[name]||name):name;
      const units=(item.units||[]).map((unit,i)=>{
        const choices=Object.values(unit.option_snapshot||{}).map(g=>`${label(g.name)}: ${(g.choices||[]).map(c=>label(c.name)).join(' / ')}`).join(' · ');
        return choices?`<p class="options">${esc(tr('وحدة','Unit'))} ${i+1}: ${esc(choices)}</p>`:'';
      }).join('');
      return `<section class="receipt-item"><div class="item-heading"><strong>${esc(item.quantity)} × ${esc(label(item.name||item.product_name))}</strong>${preparation?'':`<b class="amount">${esc(money(item.line_total_halalas))}</b>`}</div>${units}${item.note||item.notes?`<p class="item-note">${esc(tr('ملاحظة','Note'))}: ${esc(item.note||item.notes)}</p>`:''}</section>`;
    }).join('');
    return `<!doctype html><html lang="${receiptLanguage}" dir="${receiptLanguage==='en'?'ltr':'rtl'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(title)} — ${esc(orderLabel(o))}</title><style>
      *{box-sizing:border-box}html{background:#eee;color:#000;font-family:Arial,Tahoma,sans-serif}body{margin:0;--paper:80mm;font-size:13px;line-height:1.5}.print-tools{padding:16px;text-align:center}.print-tools button,.print-tools select{font:inherit;padding:8px;margin:4px}.print-tools p{margin:6px auto;max-width:480px;font-size:12px}.receipt{width:var(--paper);max-width:100%;margin:12px auto;padding:3mm;background:#fff;overflow-wrap:anywhere;height:auto;min-height:0}.receipt header{text-align:center;border-bottom:2px solid #000;padding-bottom:5px;line-height:1.3}.receipt-logo{display:block;width:20mm;height:auto;max-width:100%;margin:0 auto;filter:grayscale(1) brightness(0)}.receipt h1{font-size:18px;margin:0}.receipt h2{font-size:14px;margin:1px 0}.receipt p{margin:4px 0;white-space:pre-wrap}.receipt header p{margin:1px 0;font-size:11px}.reference{font-size:15px;font-weight:bold;direction:ltr;unicode-bidi:isolate}.receipt-meta{padding:4px 0;border-bottom:1px dashed #000}.receipt-row{display:flex;justify-content:space-between;gap:8px;margin:4px 0}.receipt-row strong{text-align:end}.receipt-item{padding:9px 0;border-bottom:1px dashed #000;break-inside:avoid}.item-heading{display:flex;align-items:start;justify-content:space-between;gap:8px}.item-heading>strong{flex:1;min-width:0}.amount{font-size:12px;max-width:40%;text-align:end}.options{font-size:12px}.item-note{font-weight:bold}.totals{padding:8px 0;break-inside:avoid}.grand-total{font-size:18px;border-top:2px solid;padding-top:6px}.receipt footer{text-align:center;border-top:1px dashed;padding-top:8px;font-size:11px}.preparation .item-heading{font-size:18px}.preparation .options,.preparation .item-note{font-size:15px}@page{size:auto;margin:0}@media print{html,body{background:#fff;width:var(--paper)}.print-tools{display:none!important}.receipt{margin:0;max-width:none;padding:3mm;height:auto;overflow:visible}footer{break-inside:avoid}}
    </style></head><body><nav class="print-tools"><button id="print-receipt" type="button">${esc(tr('طباعة','Print'))}</button><label>${esc(tr('عرض الورق','Paper width'))} <select id="paper-width"><option value="80">80 mm</option><option value="58">58 mm</option></select></label><p>${esc(tr('اختر نفس عرض الورق في إعدادات الطابعة، ومقياس 100%، وأوقف رؤوس وتذييلات المتصفح. طول الفاتورة يتمدد حسب الأصناف.','Match the printer paper width, use 100% scale and disable browser headers and footers. Receipt length grows with the items.'))}</p></nav><main class="receipt ${preparation?'preparation':''}"><header><img class="receipt-logo" src="${esc(location.origin)}/assets/kps-receipt-logo.png" alt="${esc(tr('كبز قهوة مختصة','KPS COFFEE'))}"><h1>${esc(tr('كبز قهوة مختصة','KPS COFFEE'))}</h1><h2>${esc(title)}</h2><div class="reference">${esc(orderLabel(o))}</div><p>${esc(branchLabel(o))}</p><p>${esc(datetime(o.created_at))}</p><strong>${esc(serviceName(o.service,tr))}</strong></header><div class="receipt-meta">${o.car?row(tr('السيارة','Car'),typeof o.car==='string'?o.car:Object.values(o.car).join(' · ')):''}${row(tr('حالة الطلب','Order status'),statusName(o.preparation_status,tr))}</div>${items}${o.notes?`<section class="receipt-item item-note">${esc(tr('ملاحظات الطلب','Order notes'))}: ${esc(o.notes)}</section>`:''}${preparation?'':`<section class="totals">${row(tr('الأصناف','Subtotal'),money(o.subtotal_halalas))}${Number(o.discount_halalas)>0?row(tr('الخصم','Discount'),money(o.discount_halalas)):''}${row(tr('رسوم التوصيل','Delivery fee'),money(o.delivery_fee_halalas))}<div class="grand-total">${row(tr('إجمالي الطلب','Order total'),money(o.total_halalas))}</div>${row(tr('طريقة الدفع','Payment method'),({cash:tr('كاش','Cash'),card:tr('شبكة','Card'),split:tr('كاش وشبكة','Cash and card')})[o.payment_method]||'—')}${row(tr('حالة التحصيل','Collection status'),statusName(o.payment_status,tr))}</section>`}<footer>${esc(preparation?tr('نسخة التحضير — راجع الإضافات والملاحظات','Preparation copy — check options and notes'):tr('فاتورة طلب — ليست فاتورة ضريبية','Order receipt — not a tax invoice'))}</footer>${!preparation&&o.receipt_qr?.image?`<img alt="Receipt QR" src="${esc(o.receipt_qr.image)}" style="display:block;width:100%;height:auto;aspect-ratio:1;image-rendering:pixelated;margin-top:3mm">`:''}</main></body></html>`;
  }
  async function printOrder(id, preparation=false) {
    const win=window.open('','_blank');if(!win)throw new Error(tr('اسمح بنافذة الطباعة لهذا الموقع.','Allow the print window for this site.'));win.opener=null;
    try{
      const d=await api(`/api/orders/${encodeURIComponent(id)}`),o=normalizeOrder(d.order);
      win.document.write(receiptHTML(o,preparation));win.document.close();
      win.document.getElementById('print-receipt').addEventListener('click',async()=>{try{await Promise.all([...win.document.images].map(img=>img.decode()));win.print();}catch(error){win.alert(tr('تعذر تحميل الشعار أو الرمز، أعد فتح الفاتورة.','Unable to load the logo or QR. Reopen the receipt.'));}});
      win.document.getElementById('paper-width').addEventListener('change',e=>win.document.body.style.setProperty('--paper',e.target.value==='58'?'58mm':'80mm'));
    }catch(error){win.close();throw error;}
  }
  async function reportView(id) { const d=await api(`/api/reports/${encodeURIComponent(id)}`);const r=d.report||d,s=r.snapshot||{},sub=s.shift?.submission||s.summary?.submission||{},summary=s.summary||{},variant=state.user.role==='owner'&&r.kind==='manager'?'owner':'compact',rendering=(r.renderings||[]).find(x=>x.template_version===5&&x.view_kind===variant),ready=rendering?.status==='ready',base=`/api/reports/${encodeURIComponent(id)}/renderings/v5`;modal(tr('لقطة التقرير الثابتة','Immutable report snapshot'),`<div class="stack"><p class="code">${esc(s.closure_label||shiftLabel(s.shift))} · v${esc(r.version||1)}</p><p class="small-text">${esc(tr('المعدّ','Prepared by'))}: <span class="code">${esc(s.display_users?.[s.prepared_by]||s.prepared_by||'—')}</span> · ${esc(tr('المعتمد','Approved by'))}: <span class="code">${esc(s.display_users?.[s.approved_by]||s.approved_by||'—')}</span></p>${notice(`${tr('تاريخ تشغيلي','Operational date')}: ${s.operational_date||'—'} · ${datetime(s.shift?.opened_at)} — ${datetime(s.shift?.closed_at)}`)}<dl class="data-grid">${dataItem(tr('طلبات فريدة','Unique orders'),num(summary.unique_orders))}${dataItem(tr('طلبات مكتملة','Completed orders'),num(summary.completed_orders))}${dataItem(tr('الكاش المحصل','Cash collected'),money(summary.cash_collected_halalas))}${dataItem(tr('الشبكة المحصلة','Card collected'),money(summary.card_collected_halalas))}${dataItem(tr('الكاش المسترد','Cash refunded'),money(summary.cash_refunded_halalas))}${dataItem(tr('الشبكة المستردة','Card refunded'),money(summary.card_refunded_halalas))}${dataItem(tr('المتوقع','Expected'),money(sub.expected_halalas))}${dataItem(tr('المعدود','Counted'),money(sub.counted_halalas))}${dataItem(tr('التسليم المؤكد','Confirmed handover'),money(sub.handover_halalas))}${dataItem(tr('المتبقي','Retained'),money(sub.retained_halalas))}${dataItem(tr('الفرق','Difference'),money(sub.difference_halalas),'difference')}</dl>${s.shift?.exception_reason?notice(s.shift.exception_reason,'warn'):''}<section><h3>${esc(tr('الطلبات ونتائجها','Orders and outcomes'))}</h3>${table([tr('المرجع','Reference'),tr('الفرع','Branch'),tr('الحالة','Status'),tr('المبلغ','Amount')],(s.orders||[]).map(o=>[esc(orderLabel(o)),esc(branchLabel({...o,branch_name:s.display_branches?.[o.branch_id]?.name||o.snapshot?.branch_name},s.display_branches||{})),esc(statusName(o.delivery_status||o.preparation_status)),money(o.total_halalas)]))}</section><section><h3>${esc(tr('التسليمات والاستلامات','Handovers and receipts'))}</h3>${table([tr('المرجع','Reference'),tr('المبلغ','Amount'),tr('المستلم','Recipient'),tr('الحالة','Status')],(s.transfers||[]).map(t=>[esc(t.reference),money(t.amount_halalas),esc(s.display_users?.[t.recipient_user_id]||t.recipient_user_id),badge(t.status)]))}</section><div class="actions"><a class="button quiet" target="_blank" rel="noopener" href="${base}/print">${esc(tr('طباعة','Print'))}</a><a class="button quiet" href="${base}/csv">CSV</a>${ready?`<a class="button" href="${base}/pdf">PDF</a>`:`<a class="button quiet" href="${base}/pdf">${esc(tr('توليد وتنزيل PDF قالب 5','Generate and download template 5 PDF'))}</a><button class="quiet" data-action="retry-v5-rendering" data-id="${esc(id)}">${esc(tr('إعادة توليد القالب','Retry rendering'))}</button>${notice(tr('قالب 5 قيد التوليد؛ اللقطة والتقفيلة محفوظتان.','Template 5 is pending generation; the snapshot and closure remain saved.'),'warn')}`}${r.pdf_status==='ready'?`<a class="button quiet" href="/api/reports/${encodeURIComponent(id)}/original/pdf">${esc(tr('PDF الأصلية المحفوظة','Saved original PDF'))}</a>`:''}</div></div>`); }
  async function branchAvailability() { await loadBranches();const branchId=state.filters.branch_id||(state.user.branch_ids||[])[0]; if(!branchId)throw new Error(tr('اختر فرعًا مخولًا من الفلاتر أولًا.','Choose an authorized branch from the filters first.'));const d=await api(`/api/catalog?brand_id=${encodeURIComponent(state.user.brand_id)}&branch_id=${encodeURIComponent(branchId)}`);modal(tr('إيقاف / استئناف توفر صنف بالفرع','Pause / resume branch item availability'),`<form><label>${esc(tr('الفرع','Branch'))}<input readonly value="${esc(state.branches.find(b=>b.id===branchId)?.name||branchId)}"></label><label>${esc(tr('الصنف','Item'))}<select name="product_id" required>${selectOptions(d.products||[],'',p=>p.name)}</select></label>${check(tr('إتاحة الصنف في هذا الفرع — مع بقاء قيود المدينة','Enable item in this branch — city policies stay enforced'),'available',false)}${textarea(tr('سبب التغيير','Reason for change'),'reason','',true)}${formEnd(tr('حفظ التوفر','Save availability'))}</form>`,async(fd)=>{await mutation(`/api/branches/${encodeURIComponent(branchId)}/products/${encodeURIComponent(fd.get('product_id'))}/availability`,{available:fd.has('available'),reason:fd.get('reason')});closeModal();await loadPage();}); }
