  async function resendStaffInvitation(id) {
    const staff=(state.staff||[]).find(row=>row.id===id);
    if(!staff)throw new Error(tr('الموظف غير متاح ضمن نطاقك.','Staff unavailable in your scope.'));
    const send=async()=>{
      await mutation(`/api/identity/staff/${encodeURIComponent(id)}/resend`);
      state.staff=null;
      await loadPage();
      setStatus(tr('حُفظت الدعوة في انتظار إرسال البريد؛ التفعيل بعد تحقق الموظف.','Invitation queued for email; activation requires staff verification.'));
    };
    if(state.user.role==='owner'&&['owner','admin','delivery_manager'].includes(staff.role)){
      modal(tr('تأكيد المالك لإعادة الدعوة','Owner confirmation to resend invitation'),
        `<form><p>${esc(staff.display_name)} · <bdi>${esc(staff.email)}</bdi></p>${notice(tr('ستُعاد الدعوة بنفس الصلاحيات والفروع الحالية. يظل الحساب بانتظار تحقق الموظف من بريده.','The invitation keeps the existing permissions and branches. The account still requires staff email verification.'))}${field(tr('كلمة مرور المالك الحالية','Current owner password'),'step_up_password','',{type:'password',required:true,dir:'ltr'})}${formEnd(tr('تحقق وإرسال الدعوة','Verify and send invitation'))}</form>`,
        async(fd,form)=>{
          try{await mutation('/api/identity/step-up',{password:fd.get('step_up_password')||''});}
          finally{form.reset();}
          await send();
          closeModal();
        });
      return;
    }
    await send();
  }
