  async function serviceSettings(){const cfg=state.config||await api('/api/admin/config');const services=cfg.brand?.settings?.services||{};modal(tr('خدمات البراند','Brand services'),`<form>${['delivery','pickup','car_pickup'].map(v=>check(({delivery:tr('التوصيل','Delivery'),pickup:tr('الاستلام من الفرع','Branch pickup'),car_pickup:tr('الاستلام بالسيارة','Car pickup')})[v],v,services[v]!==false)).join('')}${textarea(tr('سبب التغيير','Reason'),'reason','',true)}${notice(tr('إيقاف خدمة على مستوى البراند يمنعها للطلبات الجديدة ولا يلغي الطلبات القائمة. إتاحة الفرع والمدينة والتغطية تبقى مستقلة.','Disabling a brand service affects new orders without cancelling current orders. Branch, city and coverage eligibility remain independent.'),'warn')}${formEnd(tr('حفظ الخدمات','Save services'))}</form>`,async fd=>{await api('/api/admin/brand-services',{method:'PATCH',body:{services:Object.fromEntries(['delivery','pickup','car_pickup'].map(v=>[v,fd.has(v)])),reason:fd.get('reason')}});state.branches=[];closeModal();await loadPage();});}
  function pauseDeliveryBranch(id){
  if(state.user.role!=='owner')throw new Error(tr('الإجراء للمالك فقط.','Owner only.'));
  const current=state.config?.branches?.find(b=>b.id===id);
  if(!current)throw new Error(tr('الفرع غير متاح.','Branch unavailable.'));
  modal(tr('إيقاف توصيل فرع محدد','Pause delivery for one branch'),
    `<form>
      ${notice(tr('سيُوقف استقبال طلبات التوصيل الجديدة في هذا الفرع فقط، دون إلغاء الطلبات القائمة أو إيقاف الفروع الأخرى.','Stops new delivery orders at this branch only; existing orders and other branches are preserved.'),'warn')}
      <p><strong>${esc(current.branch_no)} · ${esc(current.name)}</strong></p>
      ${textarea(tr('سبب إيقاف التوصيل','Reason for pausing delivery'),'reason','',true)}
      ${check(tr('أؤكد إيقاف التوصيل لهذا الفرع وحده','Confirm pausing this branch only'),'confirm')}
      ${formEnd(tr('إيقاف التوصيل لهذا الفرع','Pause branch delivery'))}
    </form>`,async fd=>{
      const reason=String(fd.get('reason')||'').trim();
      if(!reason||!fd.has('confirm'))throw new Error(tr('اكتب السبب وأكد الإيقاف.','Enter a reason and confirm.'));
      await api(`/api/admin/branches/${encodeURIComponent(id)}`,{
        method:'PATCH',body:{settings:{delivery_enabled:false},reason}
      });
      state.branches=[];closeModal();await loadPage();
      setStatus(tr('تم إيقاف الطلبات الجديدة لهذا الفرع فقط.','New orders stopped for this branch only.'));
    });
}
  async function deliveryOnly(branchId=null){await loadBranches();modal(tr('التوصيل فقط','Delivery only'),`<form>${branchChecks('scope',branchId?[branchId]:[])}${notice(tr('سيُوقف الاستلام العادي والسيارة في الفروع المختارة. هذا الإجراء لا يفعل التوصيل؛ قد يصبح فرع غير مؤهل متوقفًا لجميع الطلبات الجديدة. الطلبات الحالية تبقى محفوظة.','This disables pickup and car pickup in selected branches. It does not enable delivery; an ineligible branch may accept no new orders. Current orders remain preserved.'),'warn')}${textarea(tr('سبب التغيير','Reason'),'reason','',true)}${check(tr('أؤكد إيقاف الاستلام العادي والسيارة في النطاق المحدد','I confirm disabling pickup and car pickup in selected branches'),'confirm')}${formEnd(tr('اعتماد التوصيل فقط للنطاق المحدد','Apply delivery-only policy'))}</form>`,async fd=>{if(!fd.has('confirm'))throw new Error(tr('يلزم تأكيد التغيير.','Confirm the change.'));const ids=checkedBranches(fd,'scope');if(!ids.length)throw new Error(tr('حدد فرعًا واحدًا على الأقل.','Select at least one branch.'));const result=await mutation('/api/admin/delivery-only',{branch_ids:ids,confirm:true,reason:fd.get('reason')});state.branches=[];closeModal();await loadPage();if(result.warnings?.length)setStatus(result.warnings.map(x=>typeof x==='string'?x:x.message||x.reason||'').join(' · '),true);});}
  async function performancePolicy(){await loadBranches();const d=await api('/api/performance/policies');modal(tr('معايير أداء المحافظات','Province performance policies'),`<div class="stack">${table([tr('المحافظة','Province'),tr('الأساس','Basis'),'T1','T2',tr('الإصدار','Version')],(d.policies||[]).map(p=>[esc(p.province_name||p.province_id),esc(p.metric),esc(p.t1_seconds),esc(p.t2_seconds),esc(p.version)]))}<form class="form-columns">${field(tr('معرّف المحافظة المعتمد','Approved province ID'),'province_id','',{required:true,dir:'ltr'})}${field(tr('اسم المحافظة','Province name'),'province_name','',{required:true})}<label>${esc(tr('أساس القياس','Metric basis'))}<select name="metric"><option value="delivery">${esc(tr('الطريق: استلام السائق إلى التسليم','Road: pickup to delivery'))}</option><option value="total">${esc(tr('الزمن الكلي: إنشاء الطلب إلى الإكمال','Total: order creation to completion'))}</option></select></label>${field('T1 · '+tr('بالثواني','seconds'),'t1_seconds','',{type:'number',min:1,required:true})}${field('T2 · '+tr('بالثواني','seconds'),'t2_seconds','',{type:'number',min:2,required:true})}${field(tr('سريان المعيار','Effective time'),'effective_at','',{type:'datetime-local',required:true})}${branchChecks('scope',[])}${notice(tr('حتى T1: ممتاز. بعد T1 وحتى T2: جيد. بعد T2: متأخر. المعيار الجديد لا يغير لقطات الطلبات والتقارير السابقة.','Up to T1: excellent; above T1 through T2: good; above T2: late. New policies preserve previous order and report snapshots.'))}${formEnd(tr('حفظ إصدار معيار جديد','Save new policy version'))}</form></div>`,async fd=>{const t1=Number(fd.get('t1_seconds')),t2=Number(fd.get('t2_seconds'));if(!Number.isInteger(t1)||!Number.isInteger(t2)||t2<=t1)throw new Error(tr('يجب أن يكون T2 أكبر من T1 وبالثواني الصحيحة.','T2 must exceed T1 using whole seconds.'));await mutation('/api/performance/policies',{province_id:fd.get('province_id'),province_name:fd.get('province_name'),metric:fd.get('metric'),t1_seconds:t1,t2_seconds:t2,branch_ids:checkedBranches(fd,'scope'),effective_at:`${fd.get('effective_at')}:00+03:00`});closeModal();await loadPage();});}
