  function validatedFilters(form) {
    const filters=Object.fromEntries(new FormData(form));
    if(filters.period==='custom') {
      if(!filters.start&&!filters.end) filters.period='today';
      else if(!filters.start||!filters.end) throw new Error(tr('حدد تاريخ البداية والنهاية، أو اتركهما فارغين لعرض اليوم التشغيلي.','Choose both dates, or leave both empty to show the operational day.'));
      else if(filters.start>filters.end) throw new Error(tr('تاريخ النهاية يجب أن يكون مساويًا للبداية أو بعدها.','The end date must be on or after the start date.'));
    }
    if(filters.period!=='custom'){filters.start='';filters.end='';}
    return filters;
  }
